# longest common substring seq vs rc via simple DP would be O(n^2)=9M fine
def lcs_dp(a,b):
    n,m=len(a),len(b)
    prev=[0]*(m+1); best=0; pos=(0,0)
    for i in range(1,n+1):
        cur=[0]*(m+1)
        for j in range(1,m+1):
            if a[i-1]==b[j-1]:
                cur[j]=prev[j-1]+1
                if cur[j]>best:
                    best=cur[j]; pos=(i-cur[j], j-cur[j])
        prev=cur
    return best,pos
