# GC3 per frame in windows
def gc3(s,f,w=300):
    out=[]
    for i in range(f,len(s)-w+1,w):
        win=s[i:i+w]
        c=win[2::3]
        out.append(round((c.count('G')+c.count('C'))/len(c),2))
    return out
